void StartDownloadItem(download::DownloadCreateInfo* info,
                       const download::DownloadUrlParameters::OnStartedCallback& on_started,
                       download::InProgressDownloadManager::StartDownloadItemCallback callback,
                       uint32_t id) {
  // Ensure we're on the UI thread
  DCHECK_CURRENTLY_ON(BrowserThread::UI);

  // Create the active download item
  download::DownloadItem* download_item = download::DownloadItem::Create(info);

  // Set the unique identifier for the download item
  download_item->SetId(id);

  // Start the download process
  download::InProgressDownloadManager::StartDownload(download_item);

  // Call the OnDownloadStarted function with the new download item and the provided callback
  on_started.Run(download_item, callback);
}

void StartDownloadItem(download::DownloadCreateInfo* info,
                       const download::DownloadUrlParameters::OnStartedCallback& on_started,
                       download::InProgressDownloadManager::StartDownloadItemCallback callback,
                       uint32_t id) {
  // Ensure the function is called on the UI thread
  #if DCHECK_IS_ON()
    DCHECK_CURRENTLY_ON(BrowserThread::UI);
  #endif

  // Create an active download item using the provided info and ID
  download::DownloadItem* new_download = CreateActiveDownloadItem(info, id);

  // Invoke the provided callback with the new download item
  callback.Run(new_download);

  // Process the new download creation and call OnDownloadStarted
  OnDownloadStarted(new_download, on_started);
}

void start_download_item(download::DownloadCreateInfo* info,
